True def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = {(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    out = [row[:] for row in grid]
    rows=[r for r,c in fg]; cols=[c for r,c in fg]
    top,bottom,left,right=min(rows),max(rows),min(cols),max(cols)
    gap_limit=max(2,(right-left+1)//3)
    labels={}; n=0
    for p in fg:
        if p in labels: continue
        labels[p]=n; st=[p]
        while st:
            r,c=st.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in fg and q not in labels: labels[q]=n; st.append(q)
        n+=1
    # Horizontal short gaps between separate source components.
    for r in range(h):
        ps=sorted(c for rr,c in fg if rr==r)
        for a,b in zip(ps,ps[1:]):
            if 1 < b-a <= gap_limit+1 and labels[(r,a)] != labels[(r,b)]:
                for c in range(a+1,b): out[r][c]=2
    # Current connectivity after horizontal connectors.
    def connected(p,q):
        seen={p}; st=[p]
        while st:
            r,c=st.pop()
            if (r,c)==q:return True
            for z in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0<=z[0]<h and 0<=z[1]<w and out[z[0]][z[1]]!=bg and z not in seen:
                    seen.add(z);st.append(z)
        return False
    # Snapshot connectivity after horizontal connectors; keep all independent vertical links.
    labels_now={}; cid=0
    for start in [(r,c) for r in range(h) for c in range(w) if out[r][c]!=bg]:
        if start in labels_now: continue
        labels_now[start]=cid; st=[start]
        while st:
            r,c=st.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0<=q[0]<h and 0<=q[1]<w and out[q[0]][q[1]]!=bg and q not in labels_now:
                    labels_now[q]=cid; st.append(q)
        cid+=1
    for c in range(w):
        ps=sorted(r for r,cc in fg if cc==c)
        for a,b in zip(ps,ps[1:]):
            if 1 < b-a <= gap_limit+1 and labels_now[(a,c)] != labels_now[(b,c)]:
                for r in range(a+1,b): out[r][c]=2
    # Close nearby horizontal gaps to the left/right frame when a vertical source edge exists.
    for r in range(top,bottom+1):
        row_points=[cc for rr,cc in fg if rr==r]
        if len(row_points) < 2: continue
        for c,step in ((left,1),(right,-1)):
            support=[(rr,c) for rr in (r-1,r+1) if (rr,c) in fg]
            if not support: continue
            candidates=[cc for rr,cc in fg if rr==r and 1 < abs(cc-c) <= gap_limit+1 and (cc-c)*step > 0]
            if candidates:
                qcol=min(candidates, key=lambda cc: abs(cc-c))
                for cc in range(min(c,qcol)+1,max(c,qcol)):
                    if out[r][cc] == bg: out[r][cc]=2
    # Complete the outer rectangular frame.
    edge=({(top,c) for c in range(left,right+1)}|{(bottom,c) for c in range(left,right+1)}|
          {(r,left) for r in range(top,bottom+1)}|{(r,right) for r in range(top,bottom+1)})
    for r,c in edge:
        if out[r][c]==bg: out[r][c]=2
    return out
